<?php
/** NexaBiz China-style marketplace UI V2. Exact-hash protected; CLI only. */
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
$command=$argv[1]??'--help';
if(!in_array($command,['--dry-run','--apply','--rollback','--help'],true)){fwrite(STDERR,"Invalid command.\n");exit(2);}
$root=__DIR__;
if(!is_file($root.'/artisan')||!is_file($root.'/composer.json')){fwrite(STDERR,"Put this PHP installer beside artisan and composer.json in your Laravel root.\n");exit(2);}
$backupRoot=$root.'/storage/app/nexabiz-patch-backups/2026-11-22-china-marketplace-v2';
$stateFile=$backupRoot.'/state.json';
function showLine($s){echo $s,"\n";}
function abortPatch($s,$code=1){fwrite(STDERR,$s."\n");exit($code);}
function digestFile($f){return is_file($f)?hash_file('sha256',$f):null;}
function writeSafe($path,$data){$dir=dirname($path);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Cannot create '.$dir);$temp=$path.'.nexabiztmp';if(file_put_contents($temp,$data,LOCK_EX)===false)throw new RuntimeException('Cannot write '.$temp);if(!rename($temp,$path)){@unlink($temp);throw new RuntimeException('Cannot rename '.$temp);}}
if($command==='--help'){showLine('Usage: php '.basename(__FILE__).' --dry-run | --apply | --rollback');exit(0);}
if($command==='--rollback'){
 if(!is_file($stateFile))abortPatch('No backup state found.');
 $state=json_decode(file_get_contents($stateFile),true,512,JSON_THROW_ON_ERROR);$conflicts=[];
 foreach($state['entries'] as $name=>$record)if(digestFile($root.'/'.$name)!==($record['installed']??null))$conflicts[]=$name;
 if($conflicts)abortPatch("Cannot roll back files changed since installation:\n - ".implode("\n - ",$conflicts));
 foreach($state['entries'] as $name=>$record){$path=$root.'/'.$name;if($record['previous']===null){if(is_file($path))unlink($path);}else writeSafe($path,file_get_contents($backupRoot.'/files/'.$name));showLine('RESTORED '.$name);}
 @unlink($stateFile);showLine('Rollback complete (files only). Database migrations unchanged.');exit(0);
}
if(is_file($stateFile))abortPatch('Already applied. To undo, use --rollback.');
$encoded=trim(substr(file_get_contents(__FILE__),__COMPILER_HALT_OFFSET__));
$compressed=base64_decode($encoded,true);if($compressed===false)abortPatch('Corrupt patch payload.');
$plain=gzuncompress($compressed);if($plain===false)abortPatch('Unable to decompress patch.');
$payload=json_decode($plain,true,512,JSON_THROW_ON_ERROR);$changes=[];$already=[];$conflicts=[];
foreach($payload['entries'] as $name=>$entry){
 if(!preg_match('~^(app/|routes/|database/|resources/|public/|NEXABIZ_CHINA_UI_V2_INSTALL\.md$)~',$name)||str_contains($name,'..')||str_contains($name,'\\'))abortPatch('Unsafe patch path: '.$name);
 $current=digestFile($root.'/'.$name);
 if($current===$entry['new']){$already[]=$name;continue;}
 if($current!==$entry['old']){$conflicts[]=$name;continue;}
 $changes[$name]=$entry;
}
showLine('NexaBiz China marketplace UI V2: '.count($changes).' file changes; '.count($already).' current; '.count($conflicts).' conflicts.');
if($conflicts){foreach($conflicts as $name)showLine('CONFLICT '.$name);abortPatch('This patch expects the previous ChinaOnlineBD UI patch. Resolve local file differences before retrying. No files changed.');}
if($command==='--dry-run'){foreach($changes as $name=>$entry)showLine(($entry['old']===null?'ADD ':'UPDATE ').$name);exit(0);}
if(!$changes){showLine('Files already current.');exit(0);}
$restore=[];
foreach($changes as $name=>$entry){
 $restore[$name]=['previous'=>$entry['old'],'installed'=>$entry['new']];
 if($entry['old']!==null){$backup=$backupRoot.'/files/'.$name;$dir=dirname($backup);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))abortPatch('Cannot create backup directory.');if(!copy($root.'/'.$name,$backup))abortPatch('Cannot back up '.$name);}
}
try{
 foreach($changes as $name=>$entry){$data=base64_decode($entry['data'],true);if($data===false||hash('sha256',$data)!==$entry['new'])throw new RuntimeException('Payload digest failed: '.$name);writeSafe($root.'/'.$name,$data);showLine('OK '.$name);}
 writeSafe($stateFile,json_encode(['version'=>$payload['version'],'entries'=>$restore],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 showLine('Patch installed. Originals are backed up in storage/app/nexabiz-patch-backups/.');
}catch(Throwable $e){
 fwrite(STDERR,'Error: '.$e->getMessage()."\nRestoring originals...\n");
 foreach($restore as $name=>$record){$path=$root.'/'.$name;if($record['previous']===null){if(is_file($path))@unlink($path);}else{$bak=$backupRoot.'/files/'.$name;if(is_file($bak))writeSafe($path,file_get_contents($bak));}}exit(1);
}
__halt_compiler();

